import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { DestinationService } from '../../../services/destination.service';
import { WishlistService } from '../../../services/wishlist.service';
import { Destination } from '../../../models/destination.model';

@Component({
    selector: 'app-destination-details',
    templateUrl: './destination-details.component.html',
    styleUrls: ['./destination-details.component.css']
})
export class DestinationDetailsComponent implements OnInit {
    destination: Destination | null = null;
    loading = false;
    error = '';

    constructor(
        private route: ActivatedRoute,
        private destinationService: DestinationService,
        private wishlistService: WishlistService
    ) { }

    ngOnInit(): void {
        const id = this.route.snapshot.paramMap.get('id');
        if (id) {
            this.getDestination(parseInt(id));
        }
    }

    addToWishlist(destination: Destination) {
        if (!destination.id) return;
        this.wishlistService.addToWishlist(destination.id).subscribe({
            next: () => alert('Added to wishlist!'),
            error: (e) => alert('Error adding to wishlist')
        });
    }

    getDestination(id: number): void {
        this.loading = true;
        this.destinationService.getDestinationById(id)
            .subscribe({
                next: (data) => {
                    this.destination = data.data;
                    this.loading = false;
                },
                error: (e) => {
                    this.error = 'Destination not found';
                    this.loading = false;
                }
            });
    }
}
